def is_tree(es):
    if len(es)!=n-1:
        return False
    parent=list(range(n))
    rank=[0]*n
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra==rb:
            return False
        if rank[ra]<rank[rb]:
            ra,rb=rb,ra
        parent[rb]=ra
        if rank[ra]==rank[rb]:
            rank[ra]+=1
        return True
    for u,v in es:
        if not union(u,v):
            return False
    r=find(0)
    return all(find(i)==r for i in range(n))

