from functools import lru_cache

def count_linear_extensions(n):
    prereq=[0]*n
    for i in range(1,n+1):
        mask=0
        for j in range(1,n+1):
            if j!=i and i%j==0: # j divides i and j<i automatically? no j!=i enough because if j>i cannot divide except impossible.
                mask |= 1<<(j-1)
        prereq[i-1]=mask
    @lru_cache(None)
    def dp(mask):
        if mask==(1<<n)-1:
            return 1
        total=0
        for i in range(n):
            if not (mask>>i)&1 and (prereq[i] & ~mask)==0:
                total += dp(mask | (1<<i))
        return total
    return dp(0)

for n in range(10,17):
