def K(n,r,j):
    return sum(((-1)**h)*comb(j,h)*comb(n-j,r-h) for h in range(r+1) if h<=j and r-h<=n-j)

def count(n):
    d=comb(n,1)+comb(n,2)
    ans=1
    for j in range(1,n+1):
        eig = d - (K(n,1,j)+K(n,2,j))
        ans *= eig**comb(n,j)
    ans //= 2**n
    return ans
