from math import comb
from collections import Counter

def K(n,r,j):
    return sum(((-1)**h)*comb(j,h)*comb(n-j,r-h) for h in range(r+1) if h<=j and r-h<=n-j)

def spanning_tree_factor(n):
    d=comb(n,1)+comb(n,2)
    cnt=Counter()
    for j in range(1,n+1):
        eig = d - (K(n,1,j)+K(n,2,j))
        m=comb(n,j)
        x=eig
        p=2
        while p*p<=x:
            while x%p==0:
                cnt[p]+=m
                x//=p
            p+=1 if p==2 else 2
        if x>1: cnt[x]+=m
    cnt[2]-=n
    return cnt
for n in [5,6,7,8]:
    cnt=spanning_tree_factor(n)
    print('n',n,cnt)
