def count_cyclic(d):
    # returns dict weight->count of length-d binary sequences on a cycle with no 000 or 111 cyclically
    if d==1:
        return {}
    ans={}
    for first in range(2):
        for second in range(2):
            # build positions 0..d-1, track last two bits
            @lru_cache(None)
            def dp(pos, prev2, prev1, wt):
                if pos==d:
                    # check wrap constraints involving last two and first two:
                    bits=[prev2, prev1, first, second]
                    # triples starting at d-2, d-1? Actually cyclic triples need for starts d-2 and d-1 only; others checked during build.
                    if prev2==prev1==first: return 0
                    if prev1==first==second: return 0
                    ans[wt]=ans.get(wt,0)+1
                    return 1
                total=0
                for b in (0,1):
                    if prev2==prev1==b: continue
                    dp(pos+1, prev1, b, wt+b)
                return 0
            if d==2:
                # special: sequence [first,second] length2. cyclic triples use repeated positions; need all starts 0,1.
                # word repeated gives ... first second first second ... so triple at 0: first,second,first; at1 second,first,second. never all same unless first=second.
                # if first=second then triple all same. so allowed iff different.
                if first!=second:
                    wt=first+second
                    ans[wt]=ans.get(wt,0)+1
            else:
                dp(2, first, second, first+second)
    return ans

