from math import gcd
from functools import lru_cache

def count_sequences(d):
    # returns weight count for cyclic binary sequences length d with no 000/111
    if d==1:
        return {}
    ans={}
    if d==2:
        return {1:2}
    for first in (0,1):
        for second in (0,1):
            @lru_cache(None)
            def rec(pos, prev2, prev1, wt):
                if pos==d:
                    if prev2==prev1==first: return
                    if prev1==first==second: return
                    ans[wt]=ans.get(wt,0)+1
                    return
                for b in (0,1):
                    if prev2==prev1==b: continue
                    rec(pos+1, prev1, b, wt+b)
            rec(2, first, second, first+second)
    return ans

def necklace_count(n):
    primes={p for p in range(2,n+1) if all(p%q for q in range(2,int(p**0.5)+1))}
    burn=0
    for k in range(n):
        d=gcd(n,k)
        t=n//d
        counts=count_sequences(d)
        burn += sum(c for s,c in counts.items() if t*s in primes)
    return burn//n

for n in range(10,41):
    print(n, necklace_count(n))
