from math import gcd
from functools import lru_cache

def count_seq(d, m=5):
    # cyclic sequences length d over {0,1,2} with adjacent unequal; count by digit sum mod m
    ans=[0]*m
    for first in range(3):
        @lru_cache(None)
        def rec(pos, prev, s):
            if pos==d:
                if prev!=first:
                    ans[s%m]+=1
                return
            for x in range(3):
                if x!=prev:
                    rec(pos+1, x, (s+x)%m)
        rec(1, first, first%m)
    return ans

def necklace(n,m=5):
    burn=0
    for k in range(n):
        d=gcd(n,k)
        t=n//d
        cnts=count_seq(d,m)
        for r,c in enumerate(cnts):
            if (t*r)%m==0:
                burn += c
    return burn//n

