def count_seq(d, q, m):
    ans=[0]*m
    for first in range(q):
        @lru_cache(None)
        def rec(pos, prev, s):
            if pos==d:
                if prev!=first:
                    ans[s]+=1
                return
            for x in range(q):
                if x!=prev:
                    rec(pos+1, x, (s+x)%m)
        rec(1, first, first%m)
    return ans

def necklace(n,q,m,target=0):
    burn=0
    for k in range(n):
