    tri_pairs=[[] for _ in edges]
    for e,(u,v) in enumerate(edges):
        pairs=[]
        for w in range(n):
            if w in (u,v): continue
            e1=idx[(min(u,w),max(u,w))]
            e2=idx[(min(v,w),max(v,w))]
            if e1<e2: pairs.append((e1,e2))
            else: pairs.append((e2,e1))
        tri_pairs[e]=sorted(set(pairs))
    color=[-1]*len(edges)
    order=list(range(len(edges)))
    def rec(pos):
        if pos==len(edges): return 1
