from math import gcd
MOD=10**9+7

def count_cycle_power_words_mod(d,q,m,r):
    if d<=r:
        return [0]*m
    if d<=2*r:
        from itertools import product
        ans=[0]*m
        for w in product(range(q), repeat=d):
            ok=True
            for i in range(d):
                wi=w[i]
                for t in range(1,r+1):
                    if wi==w[(i+t)%d]: ok=False; break
                if not ok: break
            if ok: ans[sum(w)%m]=(ans[sum(w)%m]+1)%MOD
        return ans
    ans=[0]*m
    from itertools import permutations
    perms=list(permutations(range(q), r))
    for init in perms:
        states={init:[0]*m}
        states[init][sum(init)%m]=1
        for _ in range(r,d):
            nstates={}
            for tup,arr in states.items():
                for z in range(q):
                    bad=False
                    for t in tup:
                        if z==t: bad=True; break
                    if bad: continue
                    key=tup[1:]+(z,)
                    out=nstates.setdefault(key,[0]*m)
                    for s,val in enumerate(arr):
                        if val:
                            out[(s+z)%m]=(out[(s+z)%m]+val)%MOD
            states=nstates
        first=init
        for tup,arr in states.items():
            ok=True
            for a in range(r):
                for b in range(a+1):
                    if tup[a]==first[b]: ok=False; break
                if not ok: break
            if ok:
                for s,val in enumerate(arr): ans[s]=(ans[s]+val)%MOD
    return ans

def burnside_rot_mod(n,q,m,r,target=0):
    invn=pow(n,MOD-2,MOD)
    total=0
    cache={}
    for k in range(n):
        d=gcd(n,k)
        if d not in cache:
            print('computing d',d)
            cache[d]=count_cycle_power_words_mod(d,q,m,r)
        cnts=cache[d]
        t=n//d
        total=(total + sum(cnts[x] for x in range(m) if (t*x-target)%m==0))%MOD
    return total*invn%MOD

print(burnside_rot_mod(60,7,13,4,0))
