            color[best]=-1;
        }
        return total;
    }

    ull count(int a,int b,int c){
        target[0]=a; target[1]=b; target[2]=c;
        uint64_t full[W]; for(int i=0;i<W;i++) full[i]=~0ULL; full[W-1]=(1ULL<<33)-1ULL;
        nodes=0;
        return dfs(E,0,0,0,full);
    }
};

int main(int argc,char**argv){
