            if(rain+maxAdd<tgtR) return;
        }
        if(rem==0){
            if(c0==tgt0&&c1==tgt1&&c2==tgt2){
                if(tgtR==-1) dist[rain]++;
                else if(rain==tgtR) dist[rain]++;
            }
